@Test
public void testDebugAndVerbosePrintCasting_1_oe() {
    final Map<Integer, String> inner = new HashMap<>(2, 1);
    inner.put(2, "B");
    inner.put(3, "C");

    final Map<Integer, Object> outer = new HashMap<>(2, 1);
    outer.put(0, inner);
    outer.put(1, "A");

    final ByteArrayOutputStream out = new ByteArrayOutputStream();
    final PrintStream outPrint = new PrintStream(out);

    try {
        MapUtils.debugPrint(outPrint, "Print Map", outer);
    } catch (final ClassCastException e) {
        fail("No Casting should be occurring!");
}
}

mut_method_definition:
public static void debugPrint(final PrintStream out, final Object label, final Map<?, ?> map) {
        verbosePrintInternal(out, label, map, new ArrayDeque<Map<?, ?>>(), true);
    }

