public void testIndexedArray_7_oe() {
    Iterator<E> iter = makeArrayIterator(testArray, 2);
    int count = 0;
    while (iter.hasNext()) {
        ++count;
        iter.next();
    }


    iter = makeArrayIterator(testArray, 1, testArray.length - 1);
    count = 0;
    while (iter.hasNext()) {
        ++count;
        iter.next();
    }


    try {
        iter = makeArrayIterator(testArray, -1);
    } catch (final ArrayIndexOutOfBoundsException aioobe) {
    }

    try {
        iter = makeArrayIterator(testArray, testArray.length + 1);
    } catch (final ArrayIndexOutOfBoundsException aioobe) {
    }

    try {
        iter = makeArrayIterator(testArray, 0, -1);
    } catch (final ArrayIndexOutOfBoundsException aioobe) {
    }

    try {
        iter = makeArrayIterator(testArray, 0, testArray.length + 1);
    } catch (final ArrayIndexOutOfBoundsException aioobe) {
    }

    try {
        iter = makeArrayIterator(testArray, 1, 1);
    } catch (final IllegalArgumentException iae) {
        fail("new ArrayIterator(Object,1,1) should NOT throw an IllegalArgumentException");
}
}

public void testListIteratorSet_3_oe() {
    final String[] testData = new String[] { "a", "b", "c" };

    final String[] result = new String[] { "0", "1", "2" };

    ListIterator<E> iter = makeArrayListIterator(testData);
    int x = 0;

    while (iter.hasNext()) {
        iter.next();
        iter.set((E) Integer.toString(x));
        x++;
    }


    iter = makeArrayListIterator(testArray);

    try {
        iter.set((E) "should fail");
    } catch (final IllegalStateException e) {
    } catch (final Throwable t) { // should never happen
        fail(t.toString());
}
}

mut_docstring:
/**
     * Throws {@link UnsupportedOperationException}
     * unless the underlying <code>Iterator</code> is a <code>ListIterator</code>.
     *
     * @param obj  the object to set
     * @throws UnsupportedOperationException if the underlying iterator is not of
     * type {@link ListIterator}
     */

mut_method_definition:
@Override
    public void set(final E obj) throws UnsupportedOperationException {
        if (iterator instanceof ListIterator) {
            @SuppressWarnings("unchecked")
            final ListIterator<E> li = (ListIterator<E>) iterator;
            li.set(obj);
            return;
        }
        throw new UnsupportedOperationException(UNSUPPORTED_OPERATION_MESSAGE);
    }

